                ELSE
                    valid := FALSE;
                    loadedID := 0;
                END_IF;
            ELSE
                valid := FALSE;
                loadedID := 0;
            END_IF;
        END_IF;
    END_IF;

    IF running AND NOT prevRunning THEN
        loadedID := loadedID;
    END_IF;

    prevLoadCmd := loadCmd;
    prevRunning := running;
END_FUNCTION_BLOCK
